SELECT CASE WHEN s.rating >= 3.5 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(oi.unit_price) AS total_unit_price FROM order_items oi LEFT OUTER JOIN products p ON oi.product_id = p.id FULL OUTER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 3.5 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket DESC;
